  "attack_progression": [
    {"step": 1, "tactic": "Initial Access — User visits compromised site", "technique": "T1189", "what_happened": "At 2026-03-01 09:14:02 CET, internal endpoint 10.20.14.88 issued an HTTP GET to http://10.108.57.177/articles/news-update-2026-q3 with a Chrome 120 user-agent and Referer https://www.google.com/search?q=corp+quarterly+news. The destination 10.108.57.177 is a known internal-facing WordPress blog used for corporate news. Suricata logged the request via standard HTTP eventing. This is the legitimate-but-compromised landing page step of a drive-by chain — the user did nothing wrong, the site itself is serving malicious content.", "chain_reason": "Suricata HTTP event with data.srcip=10.20.14.88, data.dstip=10.108.57.177, data.http.method=GET, data.url=/articles/news-update-2026-q3. The host is the corporate WordPress server — a high-value drive-by target because employees trust and routinely visit it.", "first_seen": "2026-03-01T09:14:02+0100"},
    {"step": 2, "tactic": "Stage Capabilities — Drive-by Target iframe fetch chain", "technique": "T1608.004", "what_happened": "Between 09:19:40 and 09:20:30 CET, the same endpoint 10.20.14.88 silently fetched a 3-hop redirect chain with no user interaction: (hop 1) GET http://10.108.57.177/static/v1/loader.js — a hidden iframe loader injected into the compromised WordPress article; (hop 2) GET http://cdn-adtrack.net/check?v=1 — an ad-tracker redirect gate returning HTTP 302; (hop 3) GET https://exploit-gate.com/landing?os=win&br=chrome&ver=120 — the exploit kit landing page, fingerprinting the browser. Suricata fired 'ET WEB_CLIENT Drive-by redirect' (signature_id 2014519) on the redirect chain. Each hop carried a Referer pointing at the previous hop — the classic exploit-kit redirect topology. The user never clicked anything; page_load alone triggered the chain.", "chain_reason": "Suricata HTTP events with data.srcip=10.20.14.88 traversing data.dstip=10.108.57.177 then data.http.hostname=cdn-adtrack.net then data.http.hostname=exploit-gate.com within 50 seconds, each Referer chained to the prior hop, plus Suricata signature 'ET WEB_CLIENT Drive-by redirect' sig_id 2014519. The redirect topology (legit site → ad-tracker gate → exploit kit landing) is the canonical T1608.004 staged drive-by target.", "first_seen": "2026-03-01T09:19:40+0100"},
    {"step": 3, "tactic": "Stage Capabilities — Exploit kit JS payload staged", "technique": "T1608.004", "what_happened": "Between 09:20:30 and 09:28:10 CET, endpoint 10.20.14.88 fetched three JavaScript payloads from exploit-gate.com: /_/v3/exploit_payload.js, /static/ek/heapspray.pack.js, and /cdn-edge/scripts/runtime_patch.js — each requested with a Firefox 118 user-agent (a switch from the Chrome 120 UA used on the landing page, consistent with exploit-kit UA-spoofing to match a targeted CVE). Suricata fired 'ET EXPLOIT JavaScript exploit kit landing page' on the payload fetches. The file names (heapspray, runtime_patch) are textbook browser-exploitation primitives. These are staged capabilities — the JS is positioned on exploit-gate.com ready for execution against the visiting browser.", "chain_reason": "Suricata HTTP events data.srcip=10.20.14.88 → data.http.hostname=exploit-gate.com with data.url matching *exploit_payload.js, *heapspray.pack.js, *runtime_patch.js, Referer https://exploit-gate.com/landing, plus Suricata 'ET EXPLOIT JavaScript exploit kit landing page' signature. JS payloads named after heap-spray / runtime-patch exploitation primitives = staged browser exploit capability per T1608.004.", "first_seen": "2026-03-01T09:20:30+0100"},
    {"step": 4, "tactic": "Stage Capabilities — Link Target URL shortener redirect", "technique": "T1608.005", "what_happened": "Between 09:28:30 and 09:31:48 CET, endpoint 10.20.14.88 followed three URL-shortener links (bit.ly/3xKpAtk, t.co/malstage99, short.link/exploit) each carrying Referer https://twitter.com and following up to 5 redirects. This is the Link Target sub-technique: shortened URLs obscuring the final destination and tracking clicks, layered on top of the drive-by chain. Suricata fired Wazuh rule 31109 (web attack — redirect chain) and a custom rule 92610 (iframe fetch to non-corp domain) on the cumulative activity.", "chain_reason": "Suricata HTTP events data.srcip=10.20.14.88 with data.http.hostname in {bit.ly, t.co, short.link} and short data.url paths plus high redirect counts, correlated by Wazuh rule.description 'web attack — redirect chain' (rule 31109) and rule 92610. URL shorteners + multi-redirect chains obscuring the staging destination = T1608.005 Link Target.", "first_seen": "2026-03-01T09:28:30+0100"}
